Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <algorithm>
#include <iostream>
#include <cstdio>
#include <vector>
#include <deque>
#include <cstring>
using namespace std;

vector<int> e[2020];
int ir[20][20], sc[20][20], pc[20][20];
char s[20][20], p[20][20];
int dd[20][20];
int dx[5] = {0,1,-1,0};
int dy[5] = {1,0,0,-1};
vector<int> ns[20][20], np[20][20];
int sp, pp;
int matchL[2020], matchR[2020];
bool used[2020];

void ade(int a, int b) {
    e[a].push_back(b);
    e[b].push_back(a);
}

bool dfsKuhn(int u) {
    for (int v : e[u]) {
        if (!used[v]) {
            used[v] = true;
            if (matchR[v] == 0 || dfsKuhn(matchR[v])) {
                matchL[u] = v;
                matchR[v] = u;
                return true;
            }
        }
    }
    return false;
}

int kuhn() {
    int res = 0;
    for (int i = 1; i < sp; ++i) {
        memset(used, 0, sizeof(used));
        if (matchL[i] == 0 && dfsKuhn(i))
            ++res;
    }
    return res;
}

int n, t;

void wk(int a, int b) {
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            dd[i][j] = 100000;
    deque<pair<int,int>> q;
    dd[a][b] = 0;
    q.push_back(make_pair(a,b));
    while (!q.empty()) {
        int x = q.front().first, y = q.front().second;
        q.pop_front();
        for (int i = 0; i < np[x][y].size(); ++i)
            for (int j = 0; j < ns[a][b].size(); ++j)
                ade(ns[a][b][j], np[x][y][i]);
        if (dd[x][y] == ir[x][y]) continue;
        for (int d = 0; d < 4; ++d) {
            int nx = x + dx[d], ny = y + dy[d];
            if (sc[nx][ny] != -1 && dd[nx][ny] > dd[x][y] + 1 && dd[x][y] + 1 <= ir[nx][ny]) {
                dd[nx][ny] = dd[x][y] + 1;
                q.push_back(make_pair(nx,ny));
            }
        }
    }
}

int main() {
    scanf("%d%d", &n, &t);
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            ir[i][j] = t;
    for (int i = 1; i <= n; ++i)
        scanf("%s", s[i] + 1);
    for (int i = 1; i <= n; ++i)
        scanf("%s", p[i] + 1);
    int rx, ry;
    sp = 1; pp = 1000;
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (s[i][j] == 'Z' || s[i][j] == 'Y')
                sc[i][j] = -1, ir[i][j] = 0;
            if (s[i][j] == 'Z')
                rx = i, ry = j, ir[i][j] = 0;
            if ('0' <= s[i][j] && s[i][j] <= '9')
                sc[i][j] = s[i][j] - '0';
            for (int k = 0; k < sc[i][j]; ++k)
                ns[i][j].push_back(sp++);
        }
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if ('0' <= p[i][j] && p[i][j] <= '9')
                pc[i][j] = p[i][j] - '0';
            for (int k = 0; k < pc[i][j]; ++k)
                np[i][j].push_back(pp++);
        }
    }
    deque<pair<int,int>> q;
    q.push_back(make_pair(rx, ry));
    while (!q.empty()) {
        rx = q.front().first; ry = q.front().second;
        q.pop_front();
        int nx, ny;
        for (int d = 0; d < 4; ++d) {
            nx = rx + dx[d];
            ny = ry + dy[d];
            if (ir[nx][ny] > ir[rx][ry] + 1 && sc[nx][ny] != -1) {
                ir[nx][ny] = ir[rx][ry] + 1;
                q.push_back(make_pair(nx, ny));
            }
        }
    }
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            if (sc[i][j] > 0)
                wk(i, j);
    printf("%d", kuhn());
    return 0;
}
